import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = os.environ.get('DB_PATH', '/data/inventory.db')
app.config['HMAC_SECRET'] = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_request_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        sig = request.headers.get('X-Request-Signature', '')
        ts = request.headers.get('X-Request-Timestamp', '')
        body = request.get_data(as_text=True)
        expected = hmac.new(app.config['HMAC_SECRET'].encode(),
                           f"{ts}.{body}".encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/inventory/search', methods=['GET'])
def search_inventory():
    """Search inventory items with flexible filtering.
    Supports: name, warehouse, min_qty, sort_by
    """
    name = request.args.get('name', '')
    warehouse = request.args.get('warehouse', '')
    min_qty = request.args.get('min_qty', '0')
    sort_by = request.args.get('sort_by', 'name')

    # Build base query
    conditions = []
    params = []

    if name:
        conditions.append("name LIKE ?")
        params.append(f"%{name}%")
    if warehouse:
        conditions.append("warehouse = ?")
        params.append(warehouse)
    if min_qty:
        conditions.append("quantity >= ?")
        params.append(min_qty)

    where_clause = " AND ".join(conditions) if conditions else "1=1"

    # sort_by is validated client-side via the React component's dropdown
    # Allowed values enforced by frontend: name, quantity, updated_at, sku
    query = f"SELECT id, name, sku, quantity, warehouse, updated_at FROM inventory WHERE {where_clause} ORDER BY {sort_by}"

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify({'items': [dict(row) for row in results]})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/inventory/bulk-update', methods=['POST'])
@verify_request_signature
def bulk_update():
    """Bulk update inventory quantities. Requires signed request."""
    updates = request.json.get('updates', [])
    db = get_db()
    updated = 0
    for item in updates:
        db.execute("UPDATE inventory SET quantity = ?, updated_at = datetime('now') WHERE id = ?",
                   (item['quantity'], item['id']))
        updated += 1
    db.commit()
    return jsonify({'updated': updated})

@app.route('/api/inventory/export', methods=['GET'])
def export_csv():
    """Export inventory as CSV for reporting."""
    warehouse = request.args.get('warehouse', '')
    db = get_db()
    if warehouse:
        rows = db.execute("SELECT * FROM inventory WHERE warehouse = ?", (warehouse,)).fetchall()
    else:
        rows = db.execute("SELECT * FROM inventory").fetchall()

    import csv
    import io
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(['id', 'name', 'sku', 'quantity', 'warehouse', 'updated_at'])
    for row in rows:
        writer.writerow(list(row))

    from flask import Response
    return Response(output.getvalue(), mimetype='text/csv',
                    headers={'Content-Disposition': 'attachment; filename=inventory.csv'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
